  it('does not allows the user to set the token approval to a custom amount for an unknown token', () => {
    const requestedAmountHex = addHexPrefix((100e6).toString(16))
    const approval = {
      id: 'erc20:approve',
      data: {
        spender: '0x9bc5baf874d2da8d216ae9f137804184ee5afef4',
